problems = {
  const p = [];
  if (!RE.name.test(name.trim()))
    p.push("Analysis name must start alphanumeric, then letters, digits, dot, underscore or hyphen. No spaces or slashes.");
  if (h5ad.trim().length === 0)
    p.push("A query .h5ad path is required.");
  if (cohort.trim().length &gt; 0 && !RE.cohort.test(cohort.trim()))
    p.push("Cohort must not begin or end with whitespace.");
  if (!RE.matrix.test(matrix_source))
    p.push(`Matrix source "${matrix_source}" is not .X or layers.&lt;name&gt; (a layer name cannot contain spaces).`);
  if (sample_mode === "column" && sample_column.trim().length === 0)
    p.push("Sample mode is 'column', so an obs column name is required.");
  if (!Number.isInteger(min_cells) || min_cells &lt; 1)
    p.push("Min cells per sample must be an integer of at least 1.");
  if (!Number.isInteger(cpus) || cpus &lt; 1) p.push("CPUs must be an integer of at least 1.");
  if (!Number.isInteger(mem_gb) || mem_gb &lt; 1) p.push("Memory must be an integer of at least 1 GB.");
  if (!Number.isInteger(gpus) || gpus &lt; 0) p.push("GPUs must be an integer of at least 0.");
  if (!RE.walltime.test(walltime.trim()))
    p.push("Walltime must be HH:MM:SS or D-HH:MM:SS, e.g. 12:00:00 or 1-00:00:00.");
  if (scratch.trim().length === 0) p.push("Scratch subpath is required.");
  if (output.trim().length === 0) p.push("Output subpath is required.");
  if (!Number.isInteger(seed) || seed &lt; 0 || seed &gt; 4294967295)
    p.push("Seed must be an integer between 0 and 4294967295.");
  return p;
}

// A separate, softer channel. These pass the schema but are usually mistakes.
cautions = {
  const c = [];
  if (/^results?\//.test(scratch.trim()) || /^results?\//.test(output.trim()))
    c.push("A path beginning results/ usually double-nests, because the installation's root often already ends in results. Use a bare per-run name.");
  if (cohort.trim().length === 0)
    c.push("No cohort declared, so the reference source-overlap audit cannot run. Valid, but not a canonical run.");
  if (allow_partial)
    c.push("Partial cleaning is enabled. The run is then explicitly provenance-marked as partial; false is canonical.");
  if (tier === "demo")
    c.push("Tier is 'demo'. Use 'standard' or 'canonical' for a result intended for reporting.");
  return c;
}


















Code
// YAML is emitted by hand rather than through a serializer so the comments, key order and quoting
// match contracts/examples/analysis.example.yaml exactly. Two quoting traps are load-bearing:
// walltime "12:00:00" MUST be quoted or YAML 1.1 reads it as a sexagesimal integer, and
// schema_version "1.1.0" is quoted for the same class of reason.
yamlText = {
  const q = s =&gt; JSON.stringify(String(s));          // safe double-quoted scalar
  const desc = description.trim();
  const coh = cohort.trim();
  return [
    `contract: ${FIXED.contract}`,
    `schema_version: ${q(FIXED.schema_version)}`,
    ``,
    `analysis:`,
    `  name: ${name.trim()}`,
    `  description: ${desc.length ? q(desc) : "null"}`,
    ``,
    `input:`,
    `  h5ad: ${h5ad.trim()}`,
    `  cohort: ${coh.length ? coh : "null"}`,
    ``,
    `matrix:`,
    `  source: ${matrix_source}`,
    `  normalization: ${FIXED.normalization}`,
    ``,
    `sample:`,
    `  mode: ${sample_mode}`,
    `  column: ${sample_mode === "column" ? sample_column.trim() : "null"}`,
    ``,
    `engine: ${FIXED.engine}`,
    `references:`,
    ...FIXED.references.map(r =&gt; `  - ${r}`),
    ``,
    `scgate:`,
    `  enabled: ${FIXED.scgate_enabled}`,
    `  model: ${FIXED.scgate_model}`,
    `  allow_partial: ${allow_partial}`,
    `  min_cells_per_sample: ${min_cells}`,
    ``,
    `paths:`,
    `  scratch: ${scratch.trim()}`,
    `  output: ${output.trim()}`,
    ``,
    `resources:`,
    `  cpus: ${cpus}`,
    `  mem_gb: ${mem_gb}`,
    `  gpus: ${gpus}`,
    `  walltime: ${q(walltime.trim())}`,
    ``,
    `seed: ${seed}`,
    `tier: ${tier}`,
    ``
  ].join("\n");
}









