// A download would be the obvious control here, but a page served from a sandboxed context cannot
// reliably start one, so this copies to the clipboard instead and says what it did.
viewof copied = {
  const btn = html`&lt;button class="btn btn-primary btn-sm"&gt;Copy the YAML&lt;/button&gt;`;
  const note = html`&lt;span style="margin-left:.6rem;font-size:.85rem"&gt;&lt;/span&gt;`;
  btn.onclick = async () =&gt; {
    try {
      await navigator.clipboard.writeText(yamlText);
      note.textContent = `Copied ${yamlText.split("\n").length} lines. Save as ${name.trim() || "analysis"}.yaml`;
    } catch (e) {
      note.textContent = "Clipboard blocked by the browser; select the text above and copy manually.";
    }
  };
  const el = html`&lt;div&gt;${btn}${note}&lt;/div&gt;`;
  el.value = 0;
  return el;
}
